{* Code generated by authfly/codegen from specs/widgets/sign-in.def.ts. DO NOT EDIT.
   Authfly sign-in on UI8Kit 3 primitives. Axes: method (password | magic), identifier (any | email | username),
   social (none | show: provider buttons, an extension point). Props identical to the xgen widget. *}
{import '../authfly/components.latte'}
{var $id = $p['id'] ?? ''}{var $l = $p['labels'] ?? []}{var $error = $p['error'] ?? ''}
{var $formError = $error ? $id . '-error' : null}
{var $lm = ['aria-labelledby' => ($p['landmarkLabel'] ?? '') ? null : $id . '-title', 'aria-label' => $p['landmarkLabel'] ?? null]}
{capture $c5}
{include head, $id, $p['title'] ?? '', $p['text'] ?? ''}
{include messages, $id, $error, ''}
{if ($p['social'] ?? 'none') === 'show'}
{capture $c2}{foreach $p['providers'] ?? [] as $pr}{capture $c1}{include icon, $pr['icon'] ?? ''}{$pr['title'] ?? ''}{/capture}
{include button, ($l['socialUrl'] ?? '') . '/' . ($pr['id'] ?? ''), '', afSkin('button', 'outline', 'w-full'), ['data-provider' => $pr['id'] ?? null], $c1}{/foreach}{/capture}{include stack, '2', '', '', '', ['role' => 'group', 'aria-label' => $l['providers'] ?? null, 'data-testid' => 'authfly-providers'], $c2}
{/if}
{capture $c3}{include hidden, 'csrf', $p['csrf'] ?? ''}
{include field, ['label' => $l['identifier'] ?? '', 'for' => $id . '-identifier', 'formError' => $formError, 'input' => ['type' => ($p['identifier'] ?? 'any') === 'email' ? 'email' : 'text', 'name' => 'identifier', 'required' => true, 'attrs' => ['autocomplete' => ($p['identifier'] ?? 'any') === 'email' ? 'email' : 'username']]]}
{if ($p['method'] ?? 'password') === 'password'}
{include field, ['label' => $l['password'] ?? '', 'for' => $id . '-password', 'formError' => $formError, 'input' => ['type' => 'password', 'name' => 'password', 'required' => true, 'attrs' => ['autocomplete' => 'current-password']]]}
{if $l['forgot'] ?? ''}
{include link, $l['forgotHref'] ?? '', afSkin('link', 'w-fit text-sm'), 'forgot', $l['forgot'] ?? ''}
{/if}
{/if}
{include button, '', 'submit', afSkin('button', 'default', 'w-full'), ['data-testid' => 'submit'], afEsc($l['submit'] ?? '')}{/capture}
{include form, $p['action'] ?? '', '', ['data-testid' => 'authfly-form'], $c3}
{if $l['magic'] ?? ''}
{include button, $l['magicHref'] ?? '', '', afSkin('button', 'outline', 'w-full'), ['data-testid' => 'switch-method'], afEsc($l['magic'] ?? '')}
{/if}
{if $l['signupLink'] ?? ''}
{capture $c4}{$l['signupText'] ?? ''} {include link, $l['signupHref'] ?? '', afSkin('link'), 'signup-link', $l['signupLink'] ?? ''}{/capture}
{include text, '', afText('muted'), [], $c4}
{/if}
{/capture}
{include card, afSkin('widgetCard'), ['data-testid' => 'authfly-sign-in'] + $lm, $c5}
